<script lang="ts">
 import type {HealthView} from '../generated/HealthView';
 import type {Snippet} from 'svelte';
 import {masonry} from '../masonry';
 import Card from '../components/Card.svelte';
 import Icon from '../components/Icon.svelte';
 import Gauge from '../components/Gauge.svelte';
 import Sparkline from '../components/Sparkline.svelte';
 // Health: the long view first, then this morning's vitals, then each daily metric
 // over a range with its usual band. Your day lives on Today only.
 import RangeBar from '../components/RangeBar.svelte';
 import HistoryChart from '../components/HistoryChart.svelte';
 import VitalsMonitor from '../components/VitalsMonitor.svelte';
 import IntensityCard from '../components/IntensityCard.svelte';
 import {colors,toneColor,stressColors,stressNames} from '../charts';
 import {dateLabel,num} from '../format';
 import {fitnessAgeColor,driverScale,driverRange} from '../fitness';
 let {healthData,navigate,toggleJournal,weightContent,journalBusy=false,journalOpen=$bindable(false),journalDayOpen=$bindable(null)}:{healthData:HealthView,navigate:(route:string)=>void,toggleJournal:(enabled:boolean)=>void,weightContent?:Snippet,journalBusy?:boolean,journalOpen?:boolean,journalDayOpen?:string|null}=$props();
 const usual=(kind:string):[number,number]|null=>{const r=healthData.vitals.readings.find(v=>v.kind===kind);return r?.normal?[r.normal[0],r.normal[1]]:null};
</script>
<div class="dashboard health-dashboard" {@attach masonry}>
 <Card title="Long-term health · Fitness Age" help="fitness-age">{#snippet aside()}{#if healthData.fitnessAge.change12m!=null && Math.abs(healthData.fitnessAge.change12m)>=1}<span class="pill" style:color={healthData.fitnessAge.change12m<0?colors.good:colors.poor}><Icon name={healthData.fitnessAge.change12m<0?'trend-down':'trend-up'} size={13}/>{Math.round(Math.abs(healthData.fitnessAge.change12m))} this year</span>{/if}{/snippet}<div class="age-hero"><div><div class="age-number n" style:color={healthData.fitnessAge.fitnessAge!=null?fitnessAgeColor(healthData.fitnessAge.fitnessAge,healthData.fitnessAge.chronologicalAge):undefined}>{num(healthData.fitnessAge.fitnessAge)}</div>{#if healthData.fitnessAge.fitnessAge!=null && healthData.fitnessAge.chronologicalAge!=null}<div class="age-caption">{#if healthData.fitnessAge.fitnessAge>healthData.fitnessAge.chronologicalAge}<b>{num(healthData.fitnessAge.fitnessAge-healthData.fitnessAge.chronologicalAge)} years older</b> than your age{:else}<b>{num(healthData.fitnessAge.chronologicalAge-healthData.fitnessAge.fitnessAge)} years younger</b> than your age{/if}</div>{/if}<div class="age-source">Garmin estimate{healthData.fitnessAge.recordedOn?` · ${dateLabel(healthData.fitnessAge.recordedOn)}`:''}</div></div><Sparkline values={healthData.fitnessAge.trend} w={120} h={70} color={colors.ink}/></div>{#if healthData.fitnessAge.fitnessAge!=null && healthData.fitnessAge.chronologicalAge!=null}<div class="agebar" style:--age-status={fitnessAgeColor(healthData.fitnessAge.fitnessAge,healthData.fitnessAge.chronologicalAge)}><div class="age-mark fit" style:left={Math.max(0,Math.min(100,(healthData.fitnessAge.fitnessAge-20)/50*100))+'%'}><span>YOU {num(healthData.fitnessAge.fitnessAge)}</span></div><div class="age-mark real" style:left={Math.max(0,Math.min(100,(healthData.fitnessAge.chronologicalAge-20)/50*100))+'%'}><span>AGE {num(healthData.fitnessAge.chronologicalAge)}</span></div></div>{/if}</Card>
 {#if healthData.drivers.length}<Card title="What sets it"><div class="drivers">{#each healthData.drivers as d}<div class="driver"><span>{d.name} {#if d.target!=null}<i style:color={toneColor(d.tone)}><Icon name={d.met?'check':['restingHr','bmi','bodyFat'].includes(d.key)?'trend-down':'trend-up'} size={16}/></i>{/if}</span><b class="n">{num(d.value,d.key==='bmi'||d.key==='vigorousDays'?1:0)}<small>{d.unit}</small></b><RangeBar value={d.value} scale={driverScale(d.key)} range={driverRange(d.key,d.target)} color={toneColor(d.tone)}/></div>{/each}</div></Card>{/if}
 {#if healthData.lever}<Card title="Biggest lever"><div class="lever">{#if ['restingHr','bmi','bodyFat'].includes(healthData.lever.key)}<Icon name="trend-down" size={60}/>{:else}<Gauge size={76} stroke={8} value={healthData.lever.current} max={healthData.lever.target} display={Math.round(healthData.lever.current/healthData.lever.target*100)+'%'} color={healthData.lever.current>=healthData.lever.target?colors.good:colors.fair}/>{/if}<div><b>{healthData.lever.name}</b><span>{num(healthData.lever.current)} / {num(healthData.lever.target)} {healthData.lever.unit}</span>{#if healthData.lever.ageIfMet!=null}<span class="pill">Hit {num(healthData.lever.target,1)} <Icon name="arrow-right" size={13}/> age {num(healthData.lever.ageIfMet,1)}</span>{/if}</div></div></Card>{/if}
 <VitalsMonitor vitals={healthData.vitals} open={(kind)=>navigate('metric/'+kind)}/>
 <Card title="Resting heart rate" extra="over-time" help="metric-range"><HistoryChart values={[]} endDate={healthData.date} label="Resting heart rate" unit="bpm" metric="restingHr" initialRange="days30" band={usual('restingHr')}/><button class="link-row" onclick={()=>navigate('metric/heartRate')}>Heart rate through today<Icon name="chevron" size={15}/></button></Card>
 <Card title="Overnight HRV" extra="over-time"><HistoryChart values={[]} endDate={healthData.date} label="Overnight HRV" unit="ms" metric="hrv" initialRange="days30" band={usual('hrv')}/></Card>
 <Card title="Average stress" extra="over-time"><HistoryChart values={[]} endDate={healthData.date} label="Average stress" metric="stress" initialRange="days30"/><button class="link-row" onclick={()=>navigate('metric/stress')}>Stress through today<Icon name="chevron" size={15}/></button></Card>
 <Card title="Body Battery" extra="over-time"><HistoryChart values={[]} endDate={healthData.date} label="Body Battery" metric="bodyBattery" initialRange="days30"/></Card>
 {#if weightContent}{@render weightContent()}{:else if healthData.bodyWeight}{@const weight=healthData.bodyWeight}<Card title="Weight"><div class="age-small"><div><div class="big n">{num(weight.value,1)}<small>&nbsp;{weight.unit}</small></div><div class="small">Last measured {dateLabel(weight.measuredOn)}</div></div><Sparkline values={weight.trend} w={160} h={64} color={colors.ink} fill={false} points/></div><p class="small">{#if weight.bodyFat!=null}Body fat {num(weight.bodyFat,1)}% ·&nbsp;{/if}{#if weight.bmi!=null}BMI {num(weight.bmi,1)} ·&nbsp;{/if}Last 12 weeks · recorded weigh-ins only</p></Card>{/if}
 {#if healthData.intensity}<IntensityCard intensity={healthData.intensity} open={()=>navigate('plan')}/>{/if}
 <Card title="Fitness Age history"><HistoryChart values={[]} endDate={healthData.date} label="Fitness Age" unit="years" metric="fitnessAge" initialRange="year"/></Card>
 <Card title="Garmin journal" extra="journal"><p class="small">Private lifestyle logs · last 7 days · read-only. Never in notifications.</p>{#if !healthData.journalEnabled}<button class="secondary" disabled={journalBusy} onclick={()=>void toggleJournal(true)}>Allow local journal reads</button><p class="small">Off by default. Garmin logs are fetched only after you allow them; turn off in Settings.</p>{:else if !journalOpen}<button class="secondary" onclick={()=>journalOpen=true}>Open journal</button>{:else}<button class="secondary" onclick={()=>journalOpen=false}>Close journal</button>{#each healthData.journal as day}<div class="journal-day"><b>{dateLabel(day.date)}</b><small>Garmin · {day.state==='empty'?'No entries recorded':day.state==='available'?'Recorded':day.state==='stale'?'May be out of date':day.state==='unavailable'?'Not available':'Not checked'}</small>{#each day.entries.slice(0,journalDayOpen===day.date?undefined:3) as entry}<div class="journal-entry"><span>{entry.name}</span><span>{entry.value??'Value unknown'}</span></div>{/each}{#if day.entries.length>3}<button class="journal-more" onclick={()=>journalDayOpen=journalDayOpen===day.date?null:day.date}>{journalDayOpen===day.date?'Show less':`Show ${day.entries.length-3} more`}</button>{/if}</div>{/each}{/if}</Card>

</div>
